<style scoped>
/* Each antenna turns about the point where it meets the head. The hover twitch
 * runs on `rotate` and the offline droop on `transform`, so the two compose
 * instead of one cancelling the other. */
.antenna {
  transform-box: view-box;
  transition: transform 400ms cubic-bezier(0.3, 1.4, 0.5, 1);
}
.antenna-l {
  transform-origin: 145.6px 150.9px;
}
.antenna-r {
  transform-origin: 366.4px 150.9px;
}

.brand-mark:hover .antenna-l {
  animation: twitch-l 600ms ease-in-out;
}
.brand-mark:hover .antenna-r {
  animation: twitch-r 600ms ease-in-out 60ms;
}

.offline .antenna-l {
  transform: rotate(-28deg);
}
.offline .antenna-r {
  transform: rotate(28deg);
}

@keyframes twitch-l {
  0%,
  100% {
    rotate: 0deg;
  }
  30% {
    rotate: -14deg;
  }
  65% {
    rotate: 7deg;
  }
}

@keyframes twitch-r {
  0%,
  100% {
    rotate: 0deg;
  }
  30% {
    rotate: 14deg;
  }
  65% {
    rotate: -7deg;
  }
}

@media (prefers-reduced-motion: reduce) {
  .antenna {
    transition: none;
  }
  .brand-mark:hover .antenna-l,
  .brand-mark:hover .antenna-r {
    animation: none;
  }
}
</style>
